import numpy as np
from scipy import ndimage as ndi
from PIL import Image
from rcb_brush import Session
A=np.load('/tmp/candidate5.npz')['actions'];s=Session(instance='/app/instance.json');s.reset()
for a in A:s.step(a)
s.painter.finish();T=np.array(Image.open('/app/target.png').convert('RGB'))[:,:,0]<120;lab,n=ndi.label(T)
for si,ci in [(0,1),(1,3)]:
 st=s.strokes()[si];r,c=st['mask_bbox'];a=np.asarray(st['mask'])>=128;m=np.zeros(T.shape,bool);m[r:r+a.shape[0],c:c+a.shape[1]]=a;tm=lab==ci
 yy,xx=np.where(tm|m);r0=max(0,yy.min()-30);r1=min(1024,yy.max()+31);c0=max(0,xx.min()-30);c1=min(1024,xx.max()+31);tt=tm[r0:r1,c0:c1];mm=m[r0:r1,c0:c1]
 yy,xx=np.where(tt);P=np.c_[xx-xx.mean(),yy-yy.mean()];ev,V=np.linalg.eigh(P.T@P/len(P));V=V[:,::-1];Vr=np.array([[V[1,0],V[1,1]],[V[0,0],V[0,1]]]);y,x=np.where(mm);cy,cx=y.mean(),x.mean();best=(0,None)
 for sm in np.arange(.9,1.41,.05):
  for sn in np.arange(.8,1.21,.05):
   M=Vr@np.diag([1/sm,1/sn])@Vr.T;off=np.array([cy,cx])-M@np.array([cy,cx]);tr=ndi.affine_transform(mm.astype(np.uint8),M,offset=off,output_shape=mm.shape,order=0)>0
   for dy in range(-8,13,2):
    for dx in range(-8,13,2):
     sh=np.zeros_like(tr);sy0=max(0,-dy);sy1=min(tr.shape[0],tr.shape[0]-dy);sx0=max(0,-dx);sx1=min(tr.shape[1],tr.shape[1]-dx);sh[sy0+dy:sy1+dy,sx0+dx:sx1+dx]=tr[sy0:sy1,sx0:sx1];inter=(sh&tt).sum();iou=inter/(sh|tt).sum()
     if iou>best[0]:best=(iou,(sm,sn,dx,dy,sh.sum(),tt.sum(),inter))
 print(si+1,best)
