import numpy as np
from scipy import ndimage as ndi
from PIL import Image
from rcb_brush import Session
A=np.load('/tmp/candidate6.npz')['actions'];s=Session(instance='/app/instance.json');s.reset()
for a in A:s.step(a)
s.painter.finish();T=np.array(Image.open('/app/target.png').convert('RGB'))[:,:,0]<120;lab,n=ndi.label(T)
y,x=np.where(lab==2);P=np.c_[x,y];curves=[[(480,389),(551,382),(668,357),(738,351)],[(586,407),(585,483),(583,565),(580,649)],[(398,645),(508,639),(698,614),(825,617)]];dd=[]
for curve in curves:
 d=np.full(len(P),1e5);q=np.array(curve,float)
 for a,b in zip(q[:-1],q[1:]):
  v=b-a;t=np.clip(((P-a)@v)/(v@v),0,1);d=np.minimum(d,np.linalg.norm(P-(a+t[:,None]*v),axis=1))
 dd.append(d)
li=np.argmin(np.stack(dd,1),axis=1);groups=[]
for j in range(3):
 m=np.zeros(T.shape,bool);m[y[li==j],x[li==j]]=1;groups.append(m)
targs=[lab==1,lab==3,lab==4]+groups
for i,(st,tm) in enumerate(zip(s.strokes(),targs)):
 r,c=st['mask_bbox'];a=np.asarray(st['mask'])>=128;own=np.zeros(T.shape,bool);own[r:r+a.shape[0],c:c+a.shape[1]]=a
 ys,xs=np.where(tm|own);r0=max(0,ys.min()-15);r1=min(1024,ys.max()+16);c0=max(0,xs.min()-15);c1=min(1024,xs.max()+16);tt=tm[r0:r1,c0:c1];oo=own[r0:r1,c0:c1]
 bt=tt&~ndi.binary_erosion(tt);dt=ndi.distance_transform_edt(~bt);best=(0,None)
 for rad in [-2,-1,0,1,2]:
  if rad<0: mm=ndi.binary_erosion(oo,iterations=-rad)
  elif rad>0:mm=ndi.binary_dilation(oo,iterations=rad)
  else:mm=oo
  for dy in range(-8,9):
   for dx in range(-8,9):
    sh=np.zeros_like(mm);sy0=max(0,-dy);sy1=min(mm.shape[0],mm.shape[0]-dy);sx0=max(0,-dx);sx1=min(mm.shape[1],mm.shape[1]-dx);sh[sy0+dy:sy1+dy,sx0+dx:sx1+dx]=mm[sy0:sy1,sx0:sx1]
    bo=sh&~ndi.binary_erosion(sh);do=ndi.distance_transform_edt(~bo);pr=(dt[bo]<=4.5).mean() if bo.any() else 0;re=(do[bt]<=4.5).mean() if bt.any() else 0;f=2*pr*re/(pr+re+1e-9)
    if f>best[0]:best=(f,(dx,dy,rad,pr,re))
 print(i+1,round(best[0],3),best[1])
