import numpy as np
from PIL import Image
from rcb_brush import Session
A=np.load('/tmp/candidate7.npz')['actions'];s=Session(instance='/app/instance.json');s.reset()
for a in A:s.step(a)
s.painter.finish();T=np.array(Image.open('/app/target.png').convert('RGB'))[:,:,0]<120
def own(i):
 st=s.strokes()[i];r,c=st['mask_bbox'];a=np.asarray(st['mask'])>=128;m=np.zeros(T.shape,bool);m[r:r+a.shape[0],c:c+a.shape[1]]=a;return m
def runs(a):
 x=np.where(a)[0]
 if not len(x):return []
 st=np.r_[0,np.where(np.diff(x)>1)[0]+1];en=np.r_[np.where(np.diff(x)>1)[0]+1,len(x)]
 return [(int(x[l]),int(x[h-1])) for l,h in zip(st,en)]
