import numpy as np
from rcb_brush import Session
s=Session(instance='/app/instance.json');s.reset();s.replay(np.load('/tmp/ctrl3_c.npz')['actions']);t=s.target_image()[...,0]<120;p=s.ink()>=.5
for r in range(400,651,10):
 def run(a):
  x=np.where(a[r,520:640])[0]+520
  xs=[]
  for q in np.split(x,np.where(np.diff(x)>1)[0]+1):
   if len(q)>3:xs.append((int(q[0]),int(q[-1])))
  return xs
 print(r,run(t),run(p))
PY

